package com.um.uy.oficiosya.dto.request;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.UUID;

@Data
@NoArgsConstructor
public class ChatMessageCreateRequest {
    /** Plain text; its length is checked after trimming, against app.chat.message-max-length. */
    @NotBlank(message = "El mensaje no puede estar vacío")
    private String content;

    /** Generated by the frontend (crypto.randomUUID()); sending it again returns the stored message. */
    @NotNull(message = "El identificador del mensaje es obligatorio")
    private UUID clientMessageId;

    /** Optional: the job the message is about, which has to be one between the two participants. */
    private Long jobRequestId;
}
